/**
 * T9 — the rubber floor: the blue block (id 2) and the four blue slopes (34-37).
 *
 * PLAN.md's table says "extra bounce restitution", which is both wrong about the mechanism
 * and far too mild about the effect. Rubber does not change the bounce the ball takes
 * *off* the surface — that is still `vy / -2` like any landing. What it changes is what
 * happens to the bounce **charge** on contact. The landing branch in `Ball.step()` reads
 *
 * ```java
 * if (this.x && (this.y & 8) != 0) { this.x = false; this.v += -10; }
 * else if (this.B == 0)            { this.v = 0; }
 * ```
 *
 * — and the second arm is the only thing in the whole class that ever clears `v`. The
 * charge otherwise winds up by 5 every tick a large ball is in the air, and the bounce
 * that spends it (`vy = -67 + v`) does not reset it either.
 *
 * So on an ordinary floor every bounce is identical: the landing zeroes the charge, one
 * tick's -5 goes back on, and the ball leaves at -72 for ever. On rubber, with UP held,
 * the charge is *never* cleared — it keeps the -10 and everything accumulated since the
 * first contact — and the bounces compound without bound. Measured off a blue floor, the
 * first four launches are -117, -142, -167, -192, each one 25 stronger than the last
 * because that is what the airtime between them added. `tests/entities.test.ts` asserts
 * exactly those numbers against a brick floor's flat -72.
 *
 * With UP *not* held the flag is never consumed, no bounce fires at all, and rubber is an
 * ordinary floor.
 *
 * The flag (`e.x`) is a one-shot and it is set here, in the collision scan, on any
 * overlap — including the sideways one that happens when the ball runs into a blue wall.
 *
 * ## The asymmetry we kept
 *
 * `case 2` sets `touchedSolid` (`e.w`) **only when the mask misses**, where `case 1` sets
 * it unconditionally:
 *
 * ```java
 * case 2: if (this.b(n, n2)) { this.x = true; bl = false; } else { this.w = true; }
 * case 1: if (this.b(n, n2)) { bl = false; } this.w = true;
 * ```
 *
 * `w` is what licenses the one-pixel corner nudge, so a ball wedged into the corner of a
 * blue block gets no slack and a ball in the corner of a red one does. It is transcribed
 * as found; see docs/ORIGINAL.md's list of behaviour kept even though it is wrong.
 */
import type { Entity } from './types.ts';

/** `case 2` — the blue block. */
export const BLUE_BLOCK_ID = 2;

/** `case 34: case 35: case 36: case 37:` — the blue slopes: solid, rubber, deflecting. */
export const BLUE_SLOPE_IDS = [34, 35, 36, 37] as const;

export const rubberBlock: Entity = {
  name: 'rubber floor',
  ids: [BLUE_BLOCK_ID],
  kind: 'rubber',
  handle(cell) {
    if (cell.ball.overlapsCell(cell.row, cell.col)) {
      cell.ball.onRubber = true;
      cell.free = false;
    } else {
      cell.ball.touchedSolid = true;
    }
  },
};

export const rubberSlope: Entity = {
  name: 'rubber slope',
  ids: BLUE_SLOPE_IDS,
  kind: 'rubber',
  handle(cell) {
    if (cell.ball.overlapsSlope(cell.row, cell.col, cell.id)) {
      cell.ball.onRubber = true;
      cell.free = false;
      cell.ball.touchedSolid = true;
    }
  },
};
