/**
 * T9 — the three ids the collision switch has a `case` for and nothing in.
 *
 * `case 0: case 8: case 26: break;`. They are listed rather than left to the registry's
 * "no handler" fallback because they are *deliberately* passable, and the distinction
 * matters: ids 11, 12 and everything above 54 have no case at all because nothing ever
 * writes them into a level, whereas these three are cells the ball flies through several
 * times a second.
 *
 * - **0** — empty sky (or water; the flag is in bit 6, not the id).
 * - **8** — the checkpoint marker a taken crystal leaves behind. `Crystal.ts` writes it.
 * - **26** — the lower half of a spent any-size vertical hoop. Its live form, 22, is
 *   solid-ish through the bar test; once taken, the bottom half stops colliding
 *   altogether while the top half (25) keeps its posts. See `Hoop.ts`.
 */
import type { Entity } from './types.ts';

export const INERT_IDS = [0, 8, 26] as const;

export const inert: Entity = {
  name: 'inert cell',
  ids: INERT_IDS,
  handle() {
    // `break;` — no collision, no pickup, no sound.
  },
};
