/**
 * T9 — the registry: `e.a(int row, int col, boolean)`'s `switch`, as a dispatch table.
 *
 * `CELL_HANDLERS[id]` is the `case` body for that id, or `undefined` where the switch has
 * no case. `Ball.resolveCell()` is now the three lines around this table that the original
 * has around its switch — the bounds guard, the `DYING` short-circuit, the id/water split,
 * and the single `Sound.play` at the bottom.
 *
 * The table is built at module load and **checked** while it is built: two entities may
 * not claim the same id, and every id must be either claimed or listed in
 * `UNREACHABLE_IDS`. That check is the point of the exercise. The switch it replaces is
 * 300 lines with fifteen cases for the hoops alone, and the easiest way to break it while
 * "tidying" is to drop an id — which an integer-indexed table with a partition assert
 * cannot silently do.
 *
 * Order of the imports below is the order of the cases in the original, which is worth
 * keeping because it is not the numeric order and it groups the mechanics the way the
 * author thought of them.
 */
import { crystal } from './Crystal.ts';
import { crystalBall } from './CrystalBall.ts';
import { deflator } from './Deflator.ts';
import { door } from './Door.ts';
import { gravityInverter } from './GravityInverter.ts';
import { hoop, spentHoop } from './Hoop.ts';
import { inert } from './Inert.ts';
import { inflator } from './Inflator.ts';
import { jumpBoost } from './JumpBoost.ts';
import { movingHazard } from './MovingHazard.ts';
import { rubberBlock, rubberSlope } from './RubberFloor.ts';
import { redSlope, solid } from './Solid.ts';
import { speedBoost } from './SpeedBoost.ts';
import { spike } from './Spike.ts';
import type { CellHandler, Entity } from './types.ts';

/**
 * Every mechanic, in the order `e`'s switch reaches them.
 *
 * Water is absent on purpose: it is bit 6 of a cell byte rather than a tile id, so it
 * never reaches the switch. `src/game/entities/Water.ts` documents it and owns the two
 * pure pieces `Ball.step()` uses.
 */
export const ENTITIES: readonly Entity[] = [
  inert,
  solid,
  rubberBlock,
  rubberSlope,
  redSlope,
  movingHazard,
  spike,
  crystal,
  crystalBall,
  hoop,
  spentHoop,
  door,
  deflator,
  inflator,
  gravityInverter,
  jumpBoost,
  speedBoost,
];

/** The highest id the switch has any case for. `b.a(...)` draws nothing above it either. */
export const MAX_TILE_ID = 54;

/**
 * The two ids inside 0..54 with no case and no sprite. Nothing writes them: no level file
 * contains one (T4 checked all eleven), no runtime rewrite produces one, and
 * `src/game/Tiles.ts` has holes at the same two indices. A cell holding one would be
 * passable and invisible.
 */
export const UNREACHABLE_IDS: readonly number[] = [11, 12];

function buildTable(): readonly (CellHandler | undefined)[] {
  const size = MAX_TILE_ID + 1;
  const table: (CellHandler | undefined)[] = Array.from({ length: size }, () => undefined);
  const owner: (string | undefined)[] = Array.from({ length: size }, () => undefined);

  for (const entity of ENTITIES) {
    for (const id of entity.ids) {
      if (id < 0 || id > MAX_TILE_ID) {
        throw new Error(`${entity.name} claims tile id ${id}, outside 0..${MAX_TILE_ID}`);
      }
      const taken = owner[id];
      if (taken !== undefined) {
        throw new Error(`tile id ${id} is claimed by both "${taken}" and "${entity.name}"`);
      }
      owner[id] = entity.name;
      table[id] = entity.handle;
    }
  }

  for (let id = 0; id <= MAX_TILE_ID; id++) {
    if (owner[id] === undefined && !UNREACHABLE_IDS.includes(id)) {
      throw new Error(`tile id ${id} has no entity and is not listed as unreachable`);
    }
  }

  return table;
}

/** Indexed by tile id; `undefined` means the switch had no case, i.e. inert and invisible. */
export const CELL_HANDLERS: readonly (CellHandler | undefined)[] = buildTable();

/** Which entity owns an id, for the debug overlay and the tests. */
export function entityForId(id: number): Entity | undefined {
  return ENTITIES.find((entity) => entity.ids.includes(id));
}

export type { CellContext, CellHandler, Entity } from './types.ts';
