/**
 * T9 — water. The one mechanic in PLAN.md's table with no tile id of its own: water is
 * **bit 6 of every cell byte**, not an id, so it never reaches the collision switch and
 * has no `case`. It lives entirely in the first and eighth sections of `e.b()`.
 *
 * PLAN.md: "large ball floats up, small ball sinks". Both halves are right, and the
 * asymmetry runs deeper than the direction:
 *
 * | | terminal | accel | behaviour |
 * | --- | --- | --- | --- |
 * | large, dry | +38 | +3 | falls |
 * | small, dry | +80 | +4 | falls faster, further |
 * | large, wet | **-30** | **-2** | rises |
 * | small, wet | +42 | +6 | sinks, and *accelerates harder* than in air |
 *
 * So a small ball does not merely fail to float — it sinks at 6 per tick, the strongest
 * acceleration in the game, and tops out at 42 rather than 80. Water is thick going down
 * and buoyant going up.
 *
 * Three quirks, all reproduced:
 *
 * 1. **One sample, at the centre.** `Ball.step()` reads the flag at the cell containing
 *    the ball's centre pixel — no radius, no averaging — and does not re-read it as the
 *    ball moves through the tick. Half-submerged is not a state that exists.
 * 2. **`-30` doubles as a flag.** `e.b()` tests `terminal == -30` twice instead of
 *    re-deriving "large ball, underwater", which is what `FLOAT_TERMINAL` is for. It also
 *    means the surface behaviour below keys off the *terminal velocity*, not off the ball.
 * 3. **A resting large ball is kicked loose.** A large ball that is `grounded` underwater
 *    has its velocity forced to `-10` at the top of the tick, before gravity: without it
 *    a ball that sank to the bottom before the water was drawn over it would sit there,
 *    since the buoyancy branch only accelerates a ball that is already moving.
 *
 * ## Breaking the surface
 *
 * The vertical movement loop, for a floating ball only, halves the rise every pixel it
 * travels while its *new* row is out of the water and zeroes it once it drops under a
 * pixel a tick. That is the bob: the ball shoots up, loses half its speed per pixel above
 * the surface, stalls, and falls back until buoyancy catches it again.
 *
 * The row is recomputed from the ball's new y each pixel but the **column is not** — it is
 * the column sampled at the top of the tick. A ball drifting sideways out of a water
 * column while rising keeps being damped by the water it has already left, and one drifting
 * *into* one is not damped by it. Original, kept.
 */
import { TILE_SIZE, type Level } from '../Level.ts';
import { FLOAT_TERMINAL, MIN_FALL_SPEED, floorDiv } from '../Physics.ts';

/** The `-10` a grounded large ball underwater is kicked with, before gravity. */
export const BUOYANCY_KICK = -MIN_FALL_SPEED;

/**
 * `e.b()`'s opening sample: the underwater flag of the cell holding the ball's centre.
 * Returned as the column and row too, because the movement loop reuses the *column* while
 * recomputing the row.
 */
export function sampleWater(
  level: Level,
  x: number,
  y: number,
): { col: number; row: number; underwater: boolean } {
  const col = floorDiv(x, TILE_SIZE);
  const row = floorDiv(y, TILE_SIZE);
  return { col, row, underwater: level.isUnderwater(col, row) };
}

/** `n5 == -30` — the test `e.b()` uses for "this ball is floating". */
export function isFloating(terminal: number): boolean {
  return terminal === FLOAT_TERMINAL;
}

/**
 * The surface damping, applied per pixel of rise once the ball's row is out of the water:
 * `s >>= 1`, then snapped to zero inside ±10.
 */
export function dampAtSurface(vy: number): number {
  const halved = vy >> 1;
  if (halved <= MIN_FALL_SPEED && halved >= -MIN_FALL_SPEED) return 0;
  return halved;
}
