/**
 * T9 — plain solid geometry: the red brick (id 1) and the four red slopes (30-33).
 *
 * Not in PLAN.md's entity table, because it is not a mechanic — but it owns two of the
 * switch's cases and the registry insists every id has an owner, so it is a file like the
 * rest. The blue equivalents are `RubberFloor.ts`; the only difference between the two
 * pairs is the rubber flag and how much of a fall a slope hands over sideways.
 *
 * The asymmetry in `case 1` is worth spelling out because it looks like a bug and is not
 * the one we kept: `touchedSolid` (`e.w`) is set whether or not the ball's mask actually
 * reaches the cell. It licenses the one-pixel nudge in the movement loops, and the
 * original's intent is clearly "there is a wall in the neighbourhood", not "I am touching
 * a wall". `RubberFloor.ts`'s `case 2` sets it only on a *miss*, which is the asymmetry
 * that really is odd; see docs/ORIGINAL.md.
 */
import type { Entity } from './types.ts';

/** `case 1` — red brick. */
export const BRICK_ID = 1;

/**
 * `case 30: case 31: case 32: case 33:` — the red slopes, in the four orientations
 * `SLOPE_MIRROR` mirrors `e.f` into. Solid, deflecting, not rubber.
 */
export const RED_SLOPE_IDS = [30, 31, 32, 33] as const;

export const solid: Entity = {
  name: 'solid block',
  ids: [BRICK_ID],
  kind: 'solid',
  handle(cell) {
    if (cell.ball.overlapsCell(cell.row, cell.col)) cell.free = false;
    cell.ball.touchedSolid = true;
  },
};

export const redSlope: Entity = {
  name: 'red slope',
  ids: RED_SLOPE_IDS,
  kind: 'solid',
  handle(cell) {
    // `overlapsSlope` is a test *and* the deflection: the original's predicate rewrites
    // `vx`/`vy` on its way to returning true.
    if (cell.ball.overlapsSlope(cell.row, cell.col, cell.id)) {
      cell.free = false;
      cell.ball.touchedSolid = true;
    }
  },
};
