/**
 * T9 — the gravity inverter (ids 47-50). **Not in PLAN.md's table**, and not in the
 * localization strings either: no `lang.*` entry mentions it, which is why the plan's
 * mechanic list — built from those strings — has no row for it. It is in the tile table,
 * the sprite sheet (`sprite_52`) and the collision switch all the same.
 *
 * ```java
 * case 47: case 48: case 49: case 50: {
 *     this.g = 300;
 *     n3 = 2;
 *     this.n = false;      // clear `grounded`
 *     bl = false;
 * }
 * ```
 *
 * Twelve seconds of falling upward. While `e.g` runs, `Ball.step()` negates both terminal
 * velocity and the gravity accumulator, and the bounce impulse flips from `-67 + v` to
 * `+67 + v` — so the ball rises, settles against the ceiling, and bounces *down* off it.
 * Two details make that work:
 *
 * - **`grounded` is cleared here**, in the pickup. Without it a ball that took the
 *   inverter while resting on the floor would fire this same tick's bounce with the old
 *   sign and slam downward.
 * - **The expiry tick runs upright.** When the countdown reaches zero mid-tick the code
 *   un-negates terminal and accel and clears `grounded` again, so the tick the boost ends
 *   on is a normal-gravity tick and the ball starts falling immediately rather than
 *   finishing its rise.
 *
 * The inverted landing test is the odd part of the physics and it lives in `Ball.step()`:
 * while inverted, a blocked step counts as a landing in *both* directions, which is what
 * lets the ball come to rest on a ceiling and bounce off it.
 */
import { BOOST_TICKS } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 47: case 48: case 49: case 50:` — four rotations of the one sprite. */
export const GRAVITY_INVERTER_IDS = [47, 48, 49, 50] as const;

export const gravityInverter: Entity = {
  name: 'gravity inverter',
  ids: GRAVITY_INVERTER_IDS,
  kind: 'gravity-flip',
  handle(cell) {
    cell.ball.gravityTicks = BOOST_TICKS;
    cell.sound = 'pickup';
    cell.ball.grounded = false;
    cell.free = false;
  },
};
