/**
 * T8 — the gameplay half of class `d`, which is what the ball needs to exist inside.
 *
 * `d` is the game canvas: splash, HUD, menus, key handling, level lifecycle *and* the
 * per-tick orchestration of the ball, the camera, the hazards and the door. Only the last
 * of those is T8's business, and `Ball` cannot be stepped or tested without it, so this is
 * that slice and no more: state (`Level`, `Camera`, `Door`, lives, score, hoops), the tick
 * order out of `d.a()`, and the spawn/respawn arithmetic out of `d.a(int,int,int,int,int)`
 * and `d.j()`.
 *
 * T10 owns the rest of `d` — the splash, the HUD, the menu flow, the level transitions —
 * and will wrap this rather than replace it. What is deliberately *not* here: rendering
 * (the caller drives `TileMap` and draws the ball), the banner/HUD layout, and anything to
 * do with advancing to the next level.
 *
 * ## `d.a()`'s tick order, and why it is not obvious
 *
 * ```java
 * if (this.r != 0) --this.r;                       // the "Level N" banner
 * if (aA.A < 0 || aA.A > 96) this.e();             // the ball left the band: scroll,
 * else { this.a(true); aA.b(); this.c(aA.r, aA.p); }  //   and DO NOT step it this tick
 * if (aA.C == 1) { if (j < 0) game over; else respawn; }
 * if (this.E != 0) this.l();                       // the hazards
 * if (this.aa == this.ay) this.t = true;           // every hoop taken
 * if (this.t && this.af != -1) { ... this.g(); }   // slide the door, if it is on screen
 * ```
 *
 * Two consequences are easy to miss and both are reproduced:
 *
 * - **A band scroll costs a tick of physics.** The frame the ball crosses out of the 96px
 *   play area, the view jumps 84 pixels and the ball does not move at all.
 * - **The hazards step after the ball.** So the tick a wheel runs into a stationary ball
 *   is not the tick it kills it; the ball notices on its own next move.
 */
import { Ball, DEAD, type BallSound, type BallWorld } from './Ball.ts';
import { Camera, VIEW_HEIGHT, VIEW_WIDTH } from './Camera.ts';
import { Door } from './Door.ts';
import { TILE_SIZE, type Level, type Platform } from './Level.ts';
import { hazardForCell, stepPlatforms } from './MovingPlatform.ts';
import { STARTING_LIVES } from './Physics.ts';

/** `d.r = 120` — the "Level N" banner shows for 120 ticks, i.e. 4.8 seconds. */
export const BANNER_TICKS = 120;

/** `b.af = n3 - n7 + 12 - 1` — the door's right edge, which is what `d.a()` range-checks. */
const DOOR_ANCHOR_OFFSET = TILE_SIZE - 1;

export type PlayfieldOptions = {
  /** `d.a(int, int, int)`'s third argument. `a.f()` passes 3. */
  lives?: number;
  /** Carried between levels by `d.g`. */
  score?: number;
  /** `d.B`, the invincibility cheat. */
  invincible?: boolean;
  /** Where sound goes. Left out, effects are counted and dropped. */
  onSound?: (effect: BallSound) => void;
  /**
   * Start on this tile instead of the level header's spawn.
   *
   * `d` has the same entry point — `d.a(int,int,int,int,int)` places a ball anywhere and
   * rebuilds the view around it, which is what the record-store resume uses — and
   * `tools/parity-trace.ts` needs it: a scripted walk finds a floor in a second and a
   * single-tile power-up never, so the boost, inflator and deflator comparisons start
   * the ball on the cell.
   */
  spawn?: { readonly x: number; readonly y: number };
};

export class Playfield implements BallWorld {
  readonly level: Level;

  readonly camera = new Camera();

  readonly door = new Door();

  ball: Ball;

  /** `d.g` — the running score. */
  score: number;

  /** `d.j` — lives. Below zero and the next death is game over. */
  lives: number;

  /** `d.aa` — hoops taken this level. */
  hoopsTaken = 0;

  /** `d.f`. Set by the door, and (vestigially) by the last death. */
  levelComplete = false;

  /** `d.C`. Nothing in the port reads it yet; T10's HUD will. */
  hudDirty = true;

  /** `d.t` — every hoop is taken, so the door may start sliding. */
  allHoopsTaken = false;

  /** `d.r` — ticks of "Level N" banner left. */
  bannerTicks = BANNER_TICKS;

  /** `a.a(false)`'s path: no lives left and the burst has finished. */
  gameOver = false;

  readonly invincible: boolean;

  /** Ticks run, for the debug overlay and the golden traces. */
  ticks = 0;

  private readonly onSound: ((effect: BallSound) => void) | undefined;

  constructor(level: Level, options: PlayfieldOptions = {}) {
    this.level = level;
    this.lives = options.lives ?? STARTING_LIVES;
    this.score = options.score ?? 0;
    this.invincible = options.invincible ?? false;
    this.onSound = options.onSound;

    // `d.j()`: place the ball in the spawn tile at the level's starting size, and make
    // that tile the first checkpoint.
    const spawn = options.spawn ?? level.spawn;
    this.ball = this.place(spawn.x, spawn.y, level.startBallSize);
    this.ball.setCheckpoint(spawn.x, spawn.y);
  }

  get doorOpen(): boolean {
    return this.door.open;
  }

  /**
   * `b.m * 12` — the top of the 96px play area. `Ball.canOccupy()` needs it because two
   * of `e`'s divisions truncate a *play-area* y rather than flooring a level one.
   */
  get bandTop(): number {
    return this.camera.y;
  }

  /** `d.b(int)`. */
  addScore(points: number): void {
    this.score += points;
    this.hudDirty = true;
  }

  hazardAt(col: number, row: number): Platform | undefined {
    return hazardForCell(this.level, col, row);
  }

  playSound(effect: BallSound): void {
    this.onSound?.(effect);
  }

  /**
   * `d.a(int x, int y, int size, int vx, int vy)` plus `d.j()`'s call of it — a ball
   * centred in a tile, and the camera placed around it.
   *
   * Two details of the arithmetic are the original's:
   *
   * - the centre is `tile * 12 + size / 2`, so a 12px ball sits at the tile's centre and a
   *   16px one two pixels low and right of it;
   * - the y is then **decremented by one** (`n9 = n2 - m * 12 - 1`). There is no comment
   *   and no obvious reason; it is one pixel of lift on every spawn and respawn.
   *
   * The camera's row band comes from the *un*-decremented y, as `d` computes it before
   * the decrement.
   */
  private place(col: number, row: number, size: number): Ball {
    const x = col * TILE_SIZE + (size >> 1);
    const y = row * TILE_SIZE + (size >> 1);

    this.camera.reset(this.level, x, y);
    return new Ball(this, x, y - 1, size);
  }

  /**
   * `d.a()`'s `if (aA.C == 1)` arm: a new `e` at the checkpoint, with the size the ball
   * had when the checkpoint was set, and `d`/`c`/`b` copied back over the fresh ball's
   * zeroes. Every other piece of state — velocity, boosts, held keys — starts over,
   * because the original really does construct a new object.
   */
  private respawn(): void {
    const { checkpointCol, checkpointRow, checkpointSize } = this.ball;
    this.ball = this.place(checkpointCol, checkpointRow, checkpointSize);
    this.ball.checkpointCol = checkpointCol;
    this.ball.checkpointRow = checkpointRow;
    this.ball.checkpointSize = checkpointSize;
  }

  /**
   * `b.af != -1` and the `[I, i]` range test around it: the door only slides while it is
   * on screen. `af` is set by the tile drawer to the door's right edge in buffer pixels,
   * so in world terms this is "the door's right edge is within the 128px window".
   */
  private doorOnScreen(): boolean {
    const anchor = this.camera.toScreenX(this.level.door.x * TILE_SIZE) + DOOR_ANCHOR_OFFSET;
    return anchor >= 0 && anchor <= VIEW_WIDTH;
  }

  /** One 40 ms tick, in `d.a()`'s order. */
  tick(): void {
    if (this.gameOver || this.levelComplete) return;
    this.ticks++;

    if (this.bannerTicks !== 0) this.bannerTicks--;

    const screenY = this.camera.toScreenY(this.ball.y);
    if (screenY < 0 || screenY > VIEW_HEIGHT) {
      // `d.e()`. The band moves, the ball's *world* position does not: the original shifts
      // `aA.A` by 84 and `b.m` by seven rows in opposite directions, which cancel. So the
      // shift `followVertical()` returns is deliberately not applied to the ball here.
      this.camera.followVertical(this.ball.x, this.ball.y);
    } else {
      this.ball.step();
      this.camera.follow(this.ball.x, this.ball.dx);
    }

    if (this.ball.state === DEAD) {
      if (this.lives < 0) {
        this.gameOver = true;
        // `d.a()` returns here, before the `if (this.f)` tail — which is why the
        // `levelComplete` the ball sets on its last death is never acted on.
        return;
      }
      this.respawn();
    }

    stepPlatforms(this.level);

    if (this.hoopsTaken === this.level.hoopCount) this.allHoopsTaken = true;
    if (this.allHoopsTaken && !this.door.open && this.doorOnScreen()) this.door.advance();
  }
}
