/**
 * T9 — the exit door's *cell* behaviour (id 9). The animation is `src/game/Door.ts`, the
 * one this file deliberately does not duplicate: `Door` is the sliding panel (`b.c`,
 * `b.g()`, `b.R`) and this is `e.a(...)`'s `case 9`, the four tiles the ball touches.
 *
 * ```java
 * case 9: {
 *     if (!this.b(n, n2, 9)) break;
 *     if (this.q.a.R) { this.q.f = true; n3 = 2; }
 *     else            { bl = false; }
 * }
 * ```
 *
 * The gate is `b.R`, which latches only when the panel has finished sliding — and the
 * panel only slides while every hoop is taken *and* the door is on screen (`d.a()`'s
 * `this.t && this.af != -1`). So the door is solid for six ticks after the last hoop even
 * though the level is, logically, already won; and if the last hoop is taken off-screen
 * from the door, the six ticks are spent on the way back.
 *
 * The hitbox is the ring box narrowed 4px in x (id 9 is in `overlapsCellBox`'s first
 * group), not the door's full 24x24 footprint, so the ball has to be reasonably centred
 * in the shaft rather than merely brushing the frame.
 *
 * `levelComplete` (`d.f`) is a flag, not an action: `d.a()` acts on it after the tick, and
 * T10 owns what "acts on it" means (the `Level %U completed!` screen, the next level, the
 * `Congrats!` after 011).
 */
import type { Entity } from './types.ts';

/** `case 9`. Four cells, 2x2, at the header's door position. */
export const DOOR_ID = 9;

export const door: Entity = {
  name: 'door',
  ids: [DOOR_ID],
  kind: 'door',
  handle(cell) {
    if (!cell.ball.overlapsCellBox(cell.row, cell.col, cell.id)) return;

    if (cell.world.doorOpen) {
      cell.world.levelComplete = true;
      cell.sound = 'pickup';
    } else {
      cell.free = false;
    }
  },
};
