/**
 * T9 — the speed boost (id 38). PLAN.md: "temporary higher horizontal speed".
 *
 * ```java
 * case 38: { this.h = 300; n3 = 2; bl = false; }
 * ```
 *
 * 300 ticks at 40 ms is twelve seconds. The timer (`e.h`) is decremented in the horizontal
 * drive section of the tick, and while it is non-zero the speed *cap* doubles from 50 to
 * 100 — a tenth of a pixel a tick to two tenths, i.e. 5 px/tick to 10. The acceleration
 * itself (`+6` a tick while a direction is held) does not change, so the boost is a longer
 * runway rather than a sharper one.
 *
 * `bl = false` — the boost cell blocks. Every one of the three boosts does, with no hitbox
 * test, so like the crystals they are collected on bounding-box overlap and the ball
 * cannot pass through the cell it collected them in. In practice they are placed in the
 * open where the ball brushes the cell's span and is stopped for a single pixel of travel.
 *
 * Dying clears all three timers (`e.e()`), and so does taking the same boost again —
 * re-entering the cell just re-sets 300, since the tile is not rewritten. Boost tiles are
 * permanent and re-collectible; only the crystals and the crystal ball are consumed.
 */
import { BOOST_TICKS } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 38`. */
export const SPEED_BOOST_ID = 38;

export const speedBoost: Entity = {
  name: 'speed boost',
  ids: [SPEED_BOOST_ID],
  kind: 'speed-boost',
  handle(cell) {
    cell.ball.speedTicks = BOOST_TICKS;
    cell.sound = 'pickup';
    cell.free = false;
  },
};
