/**
 * T9 — the inflator column (ids 43-46): grows a small ball back to 16px.
 *
 * ```java
 * case 43: case 44: case 45: case 46: {
 *     if (!this.b(n, n2, n4)) break;
 *     bl = false;
 *     if (this.a != 12) break;
 *     this.f();
 * }
 * ```
 *
 * The mirror image of the deflator with one difference that matters: this one **does**
 * test the ring box first (narrowed 4px in x for 43/45, in y for 44/46), so a ball can
 * pass along the edge of an inflator cell without being caught by it. The deflator has no
 * such test. Nothing in the bytecode explains the asymmetry; both are transcribed as
 * found.
 *
 * `e.f()` — `Ball.inflate()` — grows first and then hunts for somewhere the bigger mask
 * fits, stepping outward two pixels at a time and trying six positions per step: straight
 * up, up-left, up-right, straight down, down-left, down-right. The original's loop has no
 * bound and would spin forever in a sealed pocket; the port gives up after eight tiles and
 * leaves the ball where it is, which no shipped level reaches.
 */
import { BALL_SMALL } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 43: case 44: case 45: case 46:` — the column, in four rotations. */
export const INFLATOR_IDS = [43, 44, 45, 46] as const;

export const inflator: Entity = {
  name: 'inflator',
  ids: INFLATOR_IDS,
  kind: 'inflator',
  handle(cell) {
    if (!cell.ball.overlapsCellBox(cell.row, cell.col, cell.id)) return;
    cell.free = false;
    if (cell.ball.size !== BALL_SMALL) return;
    cell.ball.inflate();
  },
};
