/**
 * T9 — the spikes: ids 3, 5 (vertical columns) and 4, 6 (horizontal ones).
 *
 * `case 3: case 4: case 5: case 6:` is four lines long and the whole mechanic is in the
 * hitbox. It is not the pixel mask the solid blocks use — it is `overlapsCellBox`, a
 * rectangle overlap with the cell narrowed by four pixels along the spikes' short axis
 * (ids 3 and 5 lose 4px from each side in x, ids 4 and 6 in y). So a ball rolling along a
 * floor *past* the base of a wall of upward spikes does not die: it has to come within
 * 4px of the middle of the cell.
 *
 * The four ids are four rotations of one sprite and behave identically; the id only picks
 * which axis the box is narrowed on, and that lives in `overlapsCellBox`.
 *
 * `free = false` before `die()` matters: the ball is blocked by the spike as well as
 * killed by it, so the movement loop does not walk it another pixel into the cell during
 * the burst. (`resolveCell` also returns blocked for every cell while `state === DYING`,
 * which is what freezes the burst in place.)
 */
import type { Entity } from './types.ts';

/** `case 3: case 4: case 5: case 6:` — up, left, down, right. */
export const SPIKE_IDS = [3, 4, 5, 6] as const;

export const spike: Entity = {
  name: 'spike',
  ids: SPIKE_IDS,
  kind: 'spike',
  handle(cell) {
    if (cell.ball.overlapsCellBox(cell.row, cell.col, cell.id)) {
      cell.free = false;
      cell.ball.die();
    }
  },
};
