/**
 * T8 — class `e`, the ball, ported field by field and predicate by predicate.
 *
 * `e` is ~15KB of bytecode and the whole of the game's feel. It has been read out of all
 * three decompilers (they agree everywhere that matters, and where they phrase a ternary
 * differently the disagreement is cosmetic); docs/ORIGINAL.md carries the field rename
 * table, the annotated tick order, and the handful of original bugs kept on purpose.
 *
 * Two structural changes, both forced by earlier tasks and neither one a change in
 * behaviour:
 *
 * **Coordinates are world pixels.** In the original `e.r` is an x inside the 156px
 * horizontal *ring buffer* and `e.A` a y inside the 96px play area, and `e.o`/`e.m` are
 * the world position derived from them through six of class `b`'s scroll indices. T7
 * threw the ring buffer away (`src/game/Camera.ts`), so `x`/`y` here are world pixels
 * outright and `left`/`top` are simply `x - radius`, `y - radius`. The horizontal half of
 * the mapping `c(int,int)` does collapses to nothing, and `e.b()`'s two `r -= 156` /
 * `r += 156` wrap fixups at the end go with it.
 *
 * The *vertical* half does not collapse, which T8 got wrong and T11's oracle found: the
 * original derives its row range from the play-area y with truncating division, so the row
 * above a ball straddling the top of the band is never scanned. `canOccupy()` transcribes
 * the expression and `BallWorld` therefore has to expose `bandTop`. See that method, and
 * docs/PARITY.md finding 4.
 *
 * **Class `d` is behind an interface.** `e` reaches into its canvas for the tilemap,
 * lives, score, hoop count, the door's state, the hazards and the three sounds.
 * `BallWorld` is exactly that surface and nothing more, so the ball can be stepped in a
 * test with no Pixi, no camera and no level loader. `src/game/Playfield.ts` is the real
 * implementation.
 *
 * ## The tick, in the original's order
 *
 * `e.b()` is one method and the order inside it is load-bearing — gravity is applied
 * *after* the vertical move, and the bounce impulse after gravity, so a bounce leaves the
 * ground at exactly `±67 + charge` with no gravity subtracted that tick:
 *
 *  1. dying? count the burst down and return
 *  2. read the underwater flag at the ball's **centre** cell
 *  3. pick terminal velocity and acceleration from (size, underwater)
 *  4. gravity inversion: flip both, count the timer down
 *  5. jump boost: pin the charge to ±80, count down
 *  6. advance the nudge phase
 *  7. clamp both velocities to ±150, then floor a slow fall to 10
 *  8. **move vertically**, one pixel at a time, bouncing on contact
 *  9. accelerate toward terminal velocity
 * 10. horizontal acceleration or decay, against the speed cap
 * 11. accumulate the jump charge
 * 12. **bounce** if grounded with UP held
 * 13. **move horizontally**, one pixel at a time
 * 14. record `dx` for the camera
 *
 * Both movement loops call `canOccupy()` per pixel, and `canOccupy()` is *not* a query —
 * it collects crystals, opens hoops, triggers boosts and kills the ball. That is the
 * original's design and it is why the port keeps the speculative calls exactly where they
 * are: moving the pickup handling into a separate pass would change what a single tick
 * can collect.
 */
import {
  BALL_LARGE,
  BALL_SMALL,
  DEATH_TICKS,
  INVERTED_CEILING_SPEED,
  JUMP_BOOST_CHARGE,
  JUMP_CHARGE_PER_TICK,
  JUMP_IMPULSE,
  KEY_DIRECTIONS,
  KEY_DOWN,
  KEY_LEFT,
  KEY_RIGHT,
  KEY_UP,
  MAX_SPEED,
  MIN_FALL_SPEED,
  NUDGE_PERIOD,
  RUBBER_CHARGE,
  RUN_ACCEL,
  RUN_DECAY,
  SCORE_HOOP,
  SPEED_CAP,
  SPEED_CAP_BOOSTED,
  SPEED_UNIT,
  deflectOnSlope,
  floorDiv,
  gravityFor,
  idiv,
  maskOverlapsCell,
  maskOverlapsSlope,
  radiusFor,
  rectsOverlap,
} from './Physics.ts';
import { TILE_ID_MASK, TILE_SIZE, TILE_UNDERWATER, type Level, type Platform } from './Level.ts';
import { CELL_HANDLERS } from './entities/index.ts';
import { BUOYANCY_KICK, dampAtSurface, isFloating, sampleWater } from './entities/Water.ts';
import type { MutableCellContext } from './entities/types.ts';

/** The three OTT effects, by the name `tools/decode-ott.ts` gives their JSON. */
export type BallSound = 'pop' | 'pickup' | 'up';

/** `e.C`. 0 alive, 2 mid-burst, 1 burst finished and a respawn is due. */
export const ALIVE = 0;
export const DEAD = 1;
export const DYING = 2;

/**
 * The slice of class `d` (and, through it, class `b`) that `e` actually touches.
 * `Playfield` implements it; a test can implement it in twenty lines.
 */
export type BallWorld = {
  readonly level: Level;

  /** `d.B` — the invincibility cheat behind 7,8,7,8,9 then 8. `e.e()` returns early. */
  readonly invincible: boolean;

  /** `b.R` — the exit door has finished sliding open. */
  readonly doorOpen: boolean;

  /** `d.j` — lives in hand. Below zero is game over, so three means four attempts. */
  lives: number;

  /** `d.aa` — hoops taken. The door starts opening when it reaches `level.hoopCount`. */
  hoopsTaken: number;

  /** `d.f` — set by the door and by the last death; `d.a()` acts on it after the tick. */
  levelComplete: boolean;

  /** `d.C` — the HUD needs repainting. Kept because it is one of `e`'s writes. */
  hudDirty: boolean;

  /**
   * `b.m * 12` — the level pixel row the 96px play area starts on.
   *
   * `e` works in play-area y and turns a row index into a level row by adding `q.m`, and
   * two of its divisions truncate rather than floor, so the answers depend on where the
   * band is. See `Ball.canOccupy()`; there is no way to be exact without this.
   */
  readonly bandTop: number;

  /** `d.b(int)` — `g += n`, plus a HUD repaint. */
  addScore(points: number): void;

  /** `b.b(int,int)` — the hazard whose travel box holds this cell, or undefined. */
  hazardAt(col: number, row: number): Platform | undefined;

  /** `Sound.play(1)` — one shot, no loop. */
  playSound(effect: BallSound): void;
};

/**
 * `f()` searches outward for somewhere a newly-inflated ball fits, with no bound. The
 * original would hang the handset if there were nowhere; the shipped levels never do that,
 * but a browser tab is worse to lose than a pixel of parity, so the search gives up after
 * eight tiles and leaves the ball where it was.
 */
const MAX_INFLATE_SEARCH = TILE_SIZE * 8;

export class Ball {
  /** `e.r` — centre x. World pixels here; a ring-buffer x in the original. */
  x: number;

  /** `e.A` — centre y. World pixels here; a play-area y in the original. */
  y: number;

  /** `e.o` — world x of the left edge. Recomputed by every `canOccupy()`. */
  left: number;

  /** `e.m` — world y of the top edge. */
  top: number;

  /** `e.p` — pixels moved horizontally this tick. The camera's only input. */
  dx = 0;

  /** `e.l` — horizontal velocity, tenths of a pixel per tick. */
  vx = 0;

  /** `e.s` — vertical velocity, tenths of a pixel per tick, positive downward. */
  vy = 0;

  /** `e.y` — the held-direction bitmask. */
  keys = 0;

  /** `e.a` — diameter: 12 deflated, 16 normal. Also selects the collision mask. */
  size: number;

  /** `e.t` — `size / 2`. */
  radius: number;

  /** `e.d`, `e.c`, `e.b` — the checkpoint cell and the ball's size when it was set. */
  checkpointCol = 0;
  checkpointRow = 0;
  checkpointSize = 0;

  /** `e.C` — see `ALIVE`/`DYING`/`DEAD`. */
  state: number = ALIVE;

  /** `e.u` — ticks of burst animation left. */
  dyingTicks = 0;

  /** `e.v` — the bounce charge. Reset on contact, then wound up by 5 a tick. */
  jumpCharge = 0;

  /** `e.h` — speed boost, `e.g` — gravity inversion, `e.B` — jump boost. All 300 ticks. */
  speedTicks = 0;
  gravityTicks = 0;
  jumpTicks = 0;

  /** `e.n` — a bounce is available: the ball landed and has not moved off yet. */
  grounded = false;

  /** `e.x` — the last surface touched was rubber (id 2, or a blue slope 34-37). */
  onRubber = false;

  /** `e.w` — a solid cell is in reach, which is what licenses the one-pixel nudge. */
  touchedSolid = false;

  /** `e.F` — 0,1,2; the nudge only fires on 0. */
  nudgePhase = 0;

  readonly world: BallWorld;

  /**
   * The `CellContext`s handed to the entity handlers, one per level of recursion, grown on
   * demand and reused for ever after. `e` has no such object — its switch reads the locals
   * of one method — and a fresh one per cell would be thousands of allocations a second
   * inside the movement loops.
   *
   * It has to be a stack rather than a single object because the scan **reenters itself**:
   * the deflator and the inflator call `Ball.deflate()`/`Ball.inflate()` from inside a
   * handler, and those search for a new position with `canOccupy()`, which scans cells of
   * its own. One shared context would be clobbered by the inner scan and the outer cell's
   * `free` answer would come back as the inner one's.
   */
  private readonly cells: MutableCellContext[] = [];

  /** How deep the current `canOccupy()` scan is, i.e. which context is in use. */
  private depth = 0;

  /**
   * `e(int r, int A, int a, d q)`. `d.a(int,int,int,int,int)` builds one at
   * `(spawnTileX * 12 + size / 2, spawnTileY * 12 + size / 2 - 1)` — note the stray `- 1`
   * on y, which is the original's and is kept.
   */
  constructor(world: BallWorld, x: number, y: number, size: number) {
    this.world = world;
    this.x = x;
    this.y = y;
    this.size = size;
    this.radius = radiusFor(size);
    this.left = x - this.radius;
    this.top = y - this.radius;
  }

  /** `e.a(int,int)` — move the checkpoint to a cell, remembering the ball's size. */
  setCheckpoint(col: number, row: number): void {
    this.checkpointCol = col;
    this.checkpointRow = row;
    this.checkpointSize = this.size;
  }

  /**
   * `e.c(int)` — a key went down. Anything but the four direction bits is ignored.
   *
   * Only three of those four bits are ever *read*: `e.b()` tests 8 (bounce), 2 (right)
   * and 1 (left). Bit 4, `DOWN`, is set and cleared and nothing looks at it — the down
   * key does nothing in Bounce. Worth knowing before T12 draws a fourth touch button.
   */
  pressKey(bit: number): void {
    if (bit === KEY_UP || bit === KEY_DOWN || bit === KEY_RIGHT || bit === KEY_LEFT) {
      this.keys |= bit;
    }
  }

  /** `e.a(int)` — a key came up. */
  releaseKey(bit: number): void {
    if (bit === KEY_UP || bit === KEY_DOWN || bit === KEY_RIGHT || bit === KEY_LEFT) {
      this.keys &= ~bit;
    }
  }

  /** `e.a()` — `y &= 0xFFFFFFF0`. Called when the canvas loses the display. */
  releaseDirections(): void {
    this.keys &= ~KEY_DIRECTIONS;
  }

  /** `e.d()` — a hoop was cleared. */
  scoreHoop(): void {
    this.world.addScore(SCORE_HOOP);
    this.world.hoopsTaken++;
    this.world.hudDirty = true;
  }

  /**
   * `e.e()` — the death routine, shared by the spikes and the moving hazards. Costs a
   * life, drops every boost, and starts the five-tick burst; `d.a()` picks the respawn up
   * when `state` reaches `DEAD`.
   */
  die(): void {
    if (this.world.invincible) return;
    this.dyingTicks = DEATH_TICKS;
    this.state = DYING;
    this.dx = 0;
    this.world.lives--;
    this.speedTicks = 0;
    this.gravityTicks = 0;
    this.jumpTicks = 0;
    this.world.hudDirty = true;
    this.world.playSound('pop');
  }

  /**
   * `e.f()` — the inflator. Grows to 16 and then searches outward in 2px steps, up then
   * down, for a position the bigger mask fits in. The search order is the original's:
   * straight up, up-left, up-right, straight down, down-left, down-right.
   */
  inflate(): void {
    this.size = BALL_LARGE;
    this.radius = radiusFor(BALL_LARGE);

    for (let step = 2; step <= MAX_INFLATE_SEARCH; step++) {
      if (this.canOccupy(this.x, this.y - step)) {
        this.y -= step;
        return;
      }
      if (this.canOccupy(this.x - step, this.y - step)) {
        this.x -= step;
        this.y -= step;
        return;
      }
      if (this.canOccupy(this.x + step, this.y - step)) {
        this.x += step;
        this.y -= step;
        return;
      }
      if (this.canOccupy(this.x, this.y + step)) {
        this.y += step;
        return;
      }
      if (this.canOccupy(this.x - step, this.y + step)) {
        this.x -= step;
        this.y += step;
        return;
      }
      if (this.canOccupy(this.x + step, this.y + step)) {
        this.x += step;
        this.y += step;
        return;
      }
    }
  }

  /** `e.c()` — the deflator. Shrinks to 12 and nudges down, or up, by two pixels. */
  deflate(): void {
    this.size = BALL_SMALL;
    this.radius = radiusFor(BALL_SMALL);

    if (this.canOccupy(this.x, this.y + 2)) this.y += 2;
    else if (this.canOccupy(this.x, this.y - 2)) this.y -= 2;
  }

  /** `e.b(int,int)` — the ball's pixel mask against a whole cell. */
  overlapsCell(row: number, col: number): boolean {
    return maskOverlapsCell(this.left, this.top, this.size, col, row);
  }

  /**
   * `e.c(int,int,int)` — the mask against a slope's solid half, *with* the deflection it
   * applies on the way. The side effect is the original's: the test and the response are
   * the same method.
   */
  overlapsSlope(row: number, col: number, id: number): boolean {
    if (!maskOverlapsSlope(this.left, this.top, this.size, col, row, id)) return false;
    if (!this.grounded) {
      const deflected = deflectOnSlope(this.vx, this.vy, id);
      this.vx = deflected.vx;
      this.vy = deflected.vy;
    }
    return true;
  }

  /**
   * `e.b(int,int,int)` — a plain box overlap against the cell, narrowed by four pixels
   * for the thin things. Ids 3/5 and the vertically-stacked hoops lose 4px from each side
   * in x; ids 4/6 and the side-by-side hoops lose 4px in y. Note the ball's box is
   * `[left, left + size - 1]`, one pixel tighter than `overlapsHoopBar`'s.
   */
  overlapsCellBox(row: number, col: number, id: number): boolean {
    let cellLeft = col * TILE_SIZE;
    let cellTop = row * TILE_SIZE;
    let cellRight = cellLeft + TILE_SIZE;
    let cellBottom = cellTop + TILE_SIZE;

    switch (id) {
      case 3:
      case 5:
      case 9:
      case 13:
      case 14:
      case 17:
      case 18:
      case 21:
      case 22:
      case 43:
      case 45:
        cellLeft += 4;
        cellRight -= 4;
        break;
      case 4:
      case 6:
      case 15:
      case 16:
      case 19:
      case 20:
      case 23:
      case 24:
      case 44:
      case 46:
        cellTop += 4;
        cellBottom -= 4;
        break;
      default:
        break;
    }

    return rectsOverlap(
      this.left,
      this.top,
      this.left + this.size - 1,
      this.top + this.size - 1,
      cellLeft,
      cellTop,
      cellRight - 1,
      cellBottom - 1,
    );
  }

  /**
   * `e.a(int,int,int)` — the hoop's *bar*: the solid rim you cannot pass through, as
   * opposed to the ring you fly between. Each id insets the cell differently, and the
   * insets are transcribed rather than derived — case 21/25 in particular collapses the
   * box to a single scanline one pixel above the cell (`n7 = n5--`), which is why the
   * top half of an upright hoop catches a ball arriving from above.
   *
   * Ids with no case return false, i.e. never block.
   */
  overlapsHoopBar(row: number, col: number, id: number): boolean {
    const cellLeft = col * TILE_SIZE;
    const cellTop = row * TILE_SIZE;

    let left = cellLeft;
    let top = cellTop;
    let right = cellLeft + TILE_SIZE;
    let bottom = cellTop + TILE_SIZE;

    switch (id) {
      case 15:
      case 19:
      case 23:
      case 27:
        top += 6;
        right -= 11;
        bottom -= 6;
        break;
      case 16:
      case 20:
      case 24:
      case 28:
        left += 11;
        top += 6;
        bottom -= 6;
        break;
      case 13:
      case 17:
        left += 6;
        right -= 6;
        bottom -= 11;
        break;
      case 21:
      case 25:
        // `n7 = n5--`: the bottom becomes the (pre-decrement) top and the top drops one
        // pixel, so the box is the single row of pixels just above the cell.
        bottom = top;
        top -= 1;
        left += 6;
        right -= 6;
        break;
      case 14:
      case 18:
      case 22:
      case 26:
        left += 6;
        top += 11;
        right -= 6;
        // The one case that tightens the ball's own box by a pixel, as the original does.
        return rectsOverlap(
          this.left,
          this.top,
          this.left + this.size - 1,
          this.top + this.size - 1,
          left,
          top,
          right,
          bottom,
        );
      default:
        return false;
    }

    return rectsOverlap(
      this.left,
      this.top,
      this.left + this.size,
      this.top + this.size,
      left,
      top,
      right,
      bottom,
    );
  }

  /**
   * `this.q.m + this.A / 12` — the level row holding the ball's centre, with the
   * original's truncating division on the play-area y. `e.b()` recomputes exactly this
   * inside the vertical movement loop for the surface-damping test, and it too rounds a
   * negative play-area y toward zero rather than down.
   */
  private centreRow(): number {
    const bandTop = this.world.bandTop;
    return idiv(bandTop, TILE_SIZE) + idiv(this.y - bandTop, TILE_SIZE);
  }

  /**
   * `e.c(int,int)` — "may the ball stand at `(px, py)`?", and everything that happens
   * because it tried.
   *
   * The original derives the cells to test in **screen** space and maps each one back to
   * the level through the ring buffer. Horizontally that collapses to the cells the
   * ball's bounding box covers, because the buffer x is never negative. Vertically it
   * does *not*, and T8 got this wrong:
   *
   * ```java
   * int n3 = 0; if (n2 < 0) n3 = 12;              // n2 is the ball's play-area y
   * int n5 = (n2 - n3 - this.t) / 12;             // first row, JAVA division
   * int n7 = (n2 - n3 - 1 + this.t) / 12 + 1;     // last row, exclusive
   * ... this.a(this.q.m + n9, ...)                // + the band's top row
   * ```
   *
   * Java `/` truncates toward zero, so a ball whose top edge is above the play area but
   * whose centre is inside it — `n2 - t` in `(-12, 0)` — gets `n5 = 0` where floor
   * division would give `-1`, and **the row above the ball is never scanned**. The row is
   * a real level row (`q.m + (-1)` is in bounds whenever the band is not the first), so
   * the effect is visible: near the top of a band the original passes through a ceiling
   * tile or a hoop rim that a floor-dividing port stops against.
   *
   * T11's trace of level 005 caught it at tick 766 — the port scored a hoop and bounced
   * off its rim a tick before the original did — so the port now transcribes the
   * expression, which is why `BallWorld` has to expose the band's top (`b.m * 12`).
   * Collision genuinely depends on the scroll state in this game.
   *
   * `left`/`top` are assigned before the scan, exactly as `e.o`/`e.m` are, so the overlap
   * tests below all read the *candidate* position rather than the current one.
   */
  canOccupy(px: number, py: number): boolean {
    this.left = px - this.radius;
    this.top = py - this.radius;

    const firstCol = floorDiv(this.left, TILE_SIZE);
    const lastCol = floorDiv(px - 1 + this.radius, TILE_SIZE) + 1;

    // `n2`, `n3`, `q.m`: the candidate's play-area y, the negative-y fixup, and the row
    // the band starts on.
    const bandTop = this.world.bandTop;
    const screenY = py - bandTop;
    const fixup = screenY < 0 ? TILE_SIZE : 0;
    const bandRow = idiv(bandTop, TILE_SIZE);
    const firstRow = bandRow + idiv(screenY - fixup - this.radius, TILE_SIZE);
    const lastRow = bandRow + idiv(screenY - fixup - 1 + this.radius, TILE_SIZE) + 1;

    // Column-major, because the pickups in `resolveCell` are order-sensitive: a tick that
    // reaches two collectibles takes them in the original's order or scores differently.
    let free = true;
    for (let col = firstCol; col < lastCol; col++) {
      for (let row = firstRow; row < lastRow; row++) {
        free = this.resolveCell(row, col, free);
      }
    }
    return free;
  }

  /**
   * `e.a(int row, int col, boolean)` — one cell of the scan: the bounds guard, the burst
   * short-circuit, the id/water split, and a dispatch into whichever entity owns the id.
   *
   * T8 had the original's `switch` inline here. T9 cut it into `src/game/entities/`, one
   * module per mechanic, with a table that refuses to load if two of them claim the same
   * tile id or if an id has no owner — see `entities/index.ts`. The statements inside each
   * handler are the `case` bodies unchanged, and the golden traces prove it: the level-001
   * trace is asserted to the pixel over 497 ticks and did not move.
   *
   * Out of bounds returns *blocked*. `e` indexes `q.F[y][x]` unguarded and would throw,
   * and `Level.rawTileAt()` already reads outside the map as solid for the same reason
   * (T4); this is the guard that makes that reachable rather than a crash.
   */
  private resolveCell(row: number, col: number, wasFree: boolean): boolean {
    const level = this.world.level;
    if (row >= level.height || row < 0 || col >= level.width || col < 0) return false;

    // Nothing collides or collects during the burst.
    if (this.state === DYING) return false;

    const raw = level.rawTileAt(col, row);
    const id = raw & TILE_ID_MASK;
    const handle = CELL_HANDLERS[id];
    if (!handle) return wasFree;

    // The context for this depth, created the first time the scan gets this deep.
    const cell = (this.cells[this.depth] ??= {
      ball: this,
      world: this.world,
      level,
      row: 0,
      col: 0,
      id: 0,
      water: 0,
      free: true,
      sound: undefined,
    });
    cell.row = row;
    cell.col = col;
    cell.id = id;
    cell.water = raw & TILE_UNDERWATER;
    cell.free = wasFree;
    cell.sound = undefined;

    // `deflate()`/`inflate()` reenter `canOccupy()` from inside the handler, so the depth
    // has to be raised across the call.
    this.depth++;
    handle(cell);
    this.depth--;

    // `e`'s switch assigns a local and plays it once at the bottom, so a cell where two
    // things happen still plays a single effect.
    if (cell.sound) this.world.playSound(cell.sound);
    return cell.free;
  }

  /** `e.b()` — one 40 ms tick of the ball. See the header for the order and why. */
  step(): void {
    const startX = this.x;
    const level = this.world.level;

    if (this.state === DYING) {
      this.dx = 0;
      this.dyingTicks--;
      if (this.dyingTicks === 0) {
        this.state = DEAD;
        // Vestigial: `d.a()` sees `state === DEAD` with no lives left first and takes the
        // game-over path before it ever looks at this flag. Kept because it is one of
        // `e`'s writes, and `Playfield` reproduces the ordering that hides it.
        if (this.world.lives < 0) this.world.levelComplete = true;
      }
      return;
    }

    // Buoyancy is read at the ball's *centre* cell — one sample, no radius, and the
    // column is not refreshed as the ball moves through the tick. `entities/Water.ts` has
    // the mechanic written up; water is a flag bit, so it never reaches the cell switch.
    const { col: centreCol, underwater } = sampleWater(level, this.x, this.y);

    const gravity = gravityFor(this.size, underwater);
    let terminal = gravity.terminal;
    let accel = gravity.accel;

    if (underwater && this.size === BALL_LARGE && this.grounded) {
      // A large ball resting on the bottom is given an upward kick so it starts rising.
      this.vy = BUOYANCY_KICK;
    }

    let inverted = false;
    if (this.gravityTicks !== 0) {
      inverted = true;
      terminal *= -1;
      accel *= -1;
      this.gravityTicks--;
      if (this.gravityTicks === 0) {
        // The tick the boost expires on runs with normal gravity, not inverted.
        inverted = false;
        this.grounded = false;
        terminal *= -1;
        accel *= -1;
      }
    }

    if (this.jumpTicks !== 0) {
      if (-1 * Math.abs(this.jumpCharge) > -JUMP_BOOST_CHARGE) {
        this.jumpCharge = inverted ? JUMP_BOOST_CHARGE : -JUMP_BOOST_CHARGE;
      }
      this.jumpTicks--;
    }

    this.nudgePhase++;
    if (this.nudgePhase === NUDGE_PERIOD) this.nudgePhase = 0;

    if (this.vy < -MAX_SPEED) this.vy = -MAX_SPEED;
    else if (this.vy > MAX_SPEED) this.vy = MAX_SPEED;
    if (this.vx < -MAX_SPEED) this.vx = -MAX_SPEED;
    else if (this.vx > MAX_SPEED) this.vx = MAX_SPEED;

    // A sub-pixel fall would truncate to zero movement and hang the ball in the air.
    if (this.vy < MIN_FALL_SPEED && this.vy > 0 && !underwater && !inverted) {
      this.vy = MIN_FALL_SPEED;
    }

    // --- vertical movement -------------------------------------------------------------
    // The loop bound is re-evaluated every iteration in all three decompilers, and `vy`
    // changes inside the loop, so this is not the same as caching it — a bounce shortens
    // the remaining travel. The horizontal loop below *does* cache its bound.
    for (let i = 0; i < idiv(Math.abs(this.vy), SPEED_UNIT); i++) {
      const dir = this.vy === 0 ? 0 : this.vy < 0 ? -1 : 1;

      if (this.canOccupy(this.x, this.y + dir)) {
        this.y += dir;
        this.grounded = false;
        if (isFloating(terminal) && !level.isUnderwater(centreCol, this.centreRow())) {
          // A floating ball that has broken the surface: halve the rise, and stop it once
          // it is under a pixel a tick. This is what makes the ball bob rather than fly.
          // Note the row is recomputed and the column is not; see `entities/Water.ts`.
          this.vy = dampAtSurface(this.vy);
        }
        continue;
      }

      // Blocked. One pixel of sideways slack, once every three ticks, so a ball wedged
      // against a corner slides off it instead of sticking.
      if (this.touchedSolid && this.vx < SPEED_UNIT && this.nudgePhase === 0) {
        if (this.canOccupy(this.x + 1, this.y + dir)) {
          this.x += 1;
          this.y += dir;
          this.touchedSolid = false;
        } else if (this.canOccupy(this.x - 1, this.y + dir)) {
          this.x -= 1;
          this.y += dir;
          this.touchedSolid = false;
        }
      }

      if (dir > 0 || (inverted && dir < 0)) {
        // Landing. Note the first disjunct: under inverted gravity a *downward* blocked
        // step also counts as a landing, so the ball re-bounces off what is really a
        // ceiling. That is the original's, and it is what makes an inverted ball settle
        // against the roof.
        this.vy = idiv(this.vy * -1, 2);
        this.grounded = true;

        if (this.onRubber && (this.keys & KEY_UP) !== 0) {
          this.onRubber = false;
          this.jumpCharge += inverted ? RUBBER_CHARGE : -RUBBER_CHARGE;
        } else if (this.jumpTicks === 0) {
          this.jumpCharge = 0;
        }

        if (this.vy >= MIN_FALL_SPEED || this.vy <= -MIN_FALL_SPEED) break;
        if (inverted) {
          this.vy = -MIN_FALL_SPEED;
          break;
        }
        this.vy = MIN_FALL_SPEED;
        break;
      }

      if (dir < 0 || (inverted && dir > 0)) {
        // Ceiling. Unreachable while inverted, since both inverted cases land above.
        this.vy = inverted ? -INVERTED_CEILING_SPEED : -this.vy >> 1;
      }
    }

    // --- gravity -----------------------------------------------------------------------
    // The `accel === -2` arms are the buoyancy case, where terminal velocity is above the
    // ball rather than below it, so the comparison runs the other way. The one inside the
    // inverted branch is dead: inversion has already negated -2 into 2.
    if (inverted) {
      if (accel === -2 && this.vy < terminal) {
        this.vy += accel;
        if (this.vy > terminal) this.vy = terminal;
      } else if (!this.grounded && this.vy > terminal) {
        this.vy += accel;
        if (this.vy < terminal) this.vy = terminal;
      }
    } else if (accel === -2 && this.vy > terminal) {
      this.vy += accel;
      if (this.vy < terminal) this.vy = terminal;
    } else if (!this.grounded && this.vy < terminal) {
      this.vy += accel;
      if (this.vy > terminal) this.vy = terminal;
    }

    // --- horizontal drive --------------------------------------------------------------
    let cap = SPEED_CAP;
    if (this.speedTicks !== 0) {
      cap = SPEED_CAP_BOOSTED;
      this.speedTicks--;
    }

    if ((this.keys & KEY_RIGHT) !== 0 && this.vx < cap) this.vx += RUN_ACCEL;
    else if ((this.keys & KEY_LEFT) !== 0 && this.vx > -cap) this.vx -= RUN_ACCEL;
    else if (this.vx > 0) this.vx -= RUN_DECAY;
    else if (this.vx < 0) this.vx += RUN_DECAY;

    // The charge winds up only for the large ball, and only when the jump boost is not
    // already pinning it. It is reset to zero on contact, in the landing branch above, so
    // by the time the bounce below reads it the value is a single tick's worth: -5, or
    // -15 off a rubber floor.
    if (this.size === BALL_LARGE && this.jumpTicks === 0) {
      this.jumpCharge += inverted ? JUMP_CHARGE_PER_TICK : -JUMP_CHARGE_PER_TICK;
    }

    if (this.grounded && (this.keys & KEY_UP) !== 0) {
      this.vy = inverted ? JUMP_IMPULSE + this.jumpCharge : -JUMP_IMPULSE + this.jumpCharge;
      this.grounded = false;
    }

    // --- horizontal movement -----------------------------------------------------------
    // Bound cached, unlike the vertical loop.
    const steps = idiv(Math.abs(this.vx), SPEED_UNIT);
    for (let i = 0; i < steps; i++) {
      const dir = this.vx === 0 ? 0 : this.vx < 0 ? -1 : 1;

      if (this.canOccupy(this.x + dir, this.y)) {
        this.x += dir;
        continue;
      }
      // Blocked with no slack left: the step is simply lost and the loop keeps going.
      if (!this.touchedSolid) continue;

      this.touchedSolid = false;
      // Try to climb the obstacle, then to drop down it, then give up and rebound. The
      // sign follows gravity, so an inverted ball climbs downward.
      const climb = inverted ? 1 : -1;
      if (this.canOccupy(this.x + dir, this.y + climb)) {
        this.x += dir;
        this.y += climb;
      } else if (this.canOccupy(this.x + dir, this.y - climb)) {
        this.x += dir;
        this.y -= climb;
      } else {
        this.vx = -(this.vx >> 1);
      }
    }

    this.dx = this.x - startX;
  }
}
