/**
 * T9 — the moving hazard (id 10), and the correction PLAN.md's table needs.
 *
 * PLAN.md T9 lists "Moving platform — collision + carrying the ball". There is no such
 * thing in Bounce. The 8-byte records the level format calls platforms are spiked wheels
 * that swing along a box and kill on contact, and this file is the evidence:
 *
 * ```java
 * case 10: {
 *     final b b2 = this.q.a.b(n2, n);          // the record whose box holds this cell
 *     if (b2 == null) break;
 *     if (!b.a(this.o + 1, this.m + 1, this.o + this.a - 1, this.m + this.a - 1,
 *              b2.x, b2.y, b2.x + 24 - 1, b2.y + 24 - 1)) break;
 *     bl = false;
 *     this.e();                                 // the spikes' death routine
 * }
 * ```
 *
 * `e.e()` is the same method `case 3`-`case 6` call. Nothing anywhere assigns the ball's
 * position or velocity from a record's, so there is no carrying and no riding; three
 * separate things confirm it — this case, the artwork (`b.Q` is cell (1,3), a chain link,
 * mirrored four ways into a wheel), and the absence of any read of `b.U`/`b.T`/`b.am`/
 * `b.z` outside `b.l()` and `b.b(int,int)`.
 *
 * Two details of the geometry:
 *
 * - **The travel box is passable.** Id 10 marks the *whole* rectangle the wheel can reach,
 *   which is usually far larger than the wheel. Only the 24x24 sprite at its current
 *   offset kills, so most of an id-10 region is empty air.
 * - **Both boxes are inset by a pixel** on the top-left, and the ball's box is its
 *   bounding square rather than its mask, so this is the one hitbox in the game that is
 *   neither the pixel mask nor a plain cell rectangle.
 *
 * The wheels step *after* the ball each tick (`d.a()` calls `b.l()` below the physics), so
 * a wheel that moves into a stationary ball does not kill it that tick — the ball finds
 * out on its own next move. `src/game/MovingPlatform.ts` has the step and the lookup.
 */
import { hazardBounds } from '../MovingPlatform.ts';
import { rectsOverlap } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 10` — the travel box of one of the level's records. */
export const HAZARD_ID = 10;

export const movingHazard: Entity = {
  name: 'moving hazard',
  ids: [HAZARD_ID],
  kind: 'hazard',
  handle(cell) {
    const hazard = cell.world.hazardAt(cell.col, cell.row);
    if (!hazard) return;

    const { ball } = cell;
    const bounds = hazardBounds(hazard);
    const hit = rectsOverlap(
      ball.left + 1,
      ball.top + 1,
      ball.left + ball.size - 1,
      ball.top + ball.size - 1,
      bounds.left,
      bounds.top,
      bounds.right,
      bounds.bottom,
    );
    if (!hit) return;

    cell.free = false;
    ball.die();
  },
};
