/**
 * T9 — the deflator arch (ids 39-42): shrinks a large ball to 12px.
 *
 * ```java
 * case 39: case 40: case 41: case 42: {
 *     bl = false;
 *     if (this.a != 16) break;
 *     this.c();
 * }
 * ```
 *
 * **Always blocking, and blocking first.** There is no hitbox test — the cell is solid to
 * any ball whose bounding box reaches it, whatever its size. That is the point of the
 * mechanic: you cannot pass an arch, you can only be shrunk by it and then walk under the
 * *next* cell along. A ball that is already small is simply stopped, which is why arches
 * are always drawn with a gap beside or below them.
 *
 * `e.c()` — `Ball.deflate()` — sets the size and radius and then nudges the ball two
 * pixels **down** if that fits, else two pixels up. Down first: the small mask is 4px
 * shorter, so shrinking in place would leave the ball hanging 2px above the floor it was
 * resting on, and the nudge puts it back on the ground.
 *
 * The four ids are four rotations of one sprite and behave identically.
 */
import { BALL_LARGE } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 39: case 40: case 41: case 42:` — the arch, in four rotations. */
export const DEFLATOR_IDS = [39, 40, 41, 42] as const;

export const deflator: Entity = {
  name: 'deflator',
  ids: DEFLATOR_IDS,
  kind: 'deflator',
  handle(cell) {
    cell.free = false;
    if (cell.ball.size !== BALL_LARGE) return;
    cell.ball.deflate();
  },
};
