/**
 * T9 — the crystal (id 7): 200 points and the checkpoint.
 *
 * ```java
 * case 7: {
 *     this.q.b(200);
 *     this.q.F[this.c][this.d] = 128;      // blank the OLD checkpoint cell
 *     this.a(n2, n);                        // remember this cell, and the ball's size
 *     this.q.F[n][n2] = 136;                // leave the marker, id 8
 *     n3 = 2;                               // the "pickup" tone
 * }
 * ```
 *
 * Three things in four statements, and two of them are unusual.
 *
 * **There is no hitbox.** No `b(...)` call, no `overlapsCellBox`: reaching the cell in the
 * scan is enough, and the scan covers every cell the ball's *bounding box* touches. So the
 * crystal's pickup radius is the square around the ball, not the disc — you can take one
 * with the corner of a ball that visually misses it by a pixel or two. `CrystalBall.ts`
 * and the three boosts do the same. It is transcribed as found.
 *
 * **Both writes drop the underwater bit.** 128 is `0x80 | 0` and 136 is `0x80 | 8` — id 0
 * and id 8 with the redraw flag, and *no* `| n3`, where every hoop rewrite in the same
 * switch carefully ORs the cell's water bit back in. So taking a crystal underwater turns
 * its cell, and the cell of the previous checkpoint wherever that was, from water into
 * sky: permanently, visibly, and with consequences for buoyancy, since `Ball.step()` reads
 * the water flag at the ball's centre cell. It is one of the six original bugs kept on
 * purpose (docs/ORIGINAL.md).
 *
 * The checkpoint records the ball's *current size* along with the cell (`e.b = e.a`), and
 * `Playfield.respawn()` builds the replacement ball at that size — so a crystal taken
 * while deflated respawns you deflated, even in a level that starts large.
 */
import { TILE_REDRAW } from '../Level.ts';
import { SCORE_CRYSTAL } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 7`. */
export const CRYSTAL_ID = 7;

/** `F[c][d] = 128` — id 0, redraw set, underwater bit **not** preserved. */
export const RAW_EMPTY = TILE_REDRAW | 0;

/** `F[n][n2] = 136` — id 8, the checkpoint marker, same missing water bit. */
export const RAW_CHECKPOINT = TILE_REDRAW | 8;

export const crystal: Entity = {
  name: 'crystal',
  ids: [CRYSTAL_ID],
  kind: 'crystal',
  handle(cell) {
    const { ball, level } = cell;
    cell.world.addScore(SCORE_CRYSTAL);
    level.setRawTileAt(ball.checkpointCol, ball.checkpointRow, RAW_EMPTY);
    ball.setCheckpoint(cell.col, cell.row);
    level.setRawTileAt(cell.col, cell.row, RAW_CHECKPOINT);
    cell.sound = 'pickup';
  },
};
