/**
 * T8 — the numbers and the pure predicates out of class `e`.
 *
 * Everything here is a transcription. `Ball.ts` holds the state machine; this file holds
 * the constants it reads, the three static `byte[][]` tables it collides against, and the
 * handful of tests that are pure functions of a position. Splitting them out is not
 * decoration: the tables are the part most likely to contain a transcription slip, and
 * they are far easier to test in isolation.
 *
 * ## The numeric representation
 *
 * The original is **all integers, no fixed point in the usual sense**, and the port keeps
 * that exactly — no floats reach the simulation.
 *
 * - **Position** (`e.r`, `e.A`) is whole pixels, at the ball's centre. There is no
 *   sub-pixel position and no accumulator.
 * - **Velocity** (`e.l`, `e.s`) is *tenths of a pixel per tick*, clamped to ±150 — so
 *   ±15 px/tick, 375 px/s at 25 Hz. Positive `s` is downward.
 * - **Movement quantises and throws the remainder away.** `e.b()` steps the ball
 *   `Math.abs(v) / 10` times by one pixel; Java integer division truncates, so a ball at
 *   `s = 39` moves 3 pixels this tick, not 3.9, and the 0.9 is *not* carried forward. The
 *   ball's speed is therefore a staircase in 10-unit steps, which is why so many of the
 *   constants below are multiples of 10.
 *
 * That last point is the whole reason PLAN.md §T8 insists on not switching to floats: a
 * float integrator would carry the remainder, the staircase would smooth out, and every
 * bounce apex would land a pixel or two off.
 *
 * Java `>>` on a negative int floors and `/` truncates, and the original uses both. The
 * two are *not* interchangeable on negatives, so each site is transcribed with the
 * operator it actually uses — `idiv()` where the original divides, `>>` where it shifts.
 * JavaScript's `>>` already matches Java's.
 */
import { TILE_SIZE, BALL_LARGE, BALL_SMALL } from './Level.ts';

/** Velocity unit: `e.b()` moves one pixel per ten units of `e.l`/`e.s`. */
export const SPEED_UNIT = 10;

/** `e.b()`'s `if (s < -150) s = -150; else if (s > 150) s = 150;`, on both axes. */
export const MAX_SPEED = 150;

/**
 * `if (s < 10 && s > 0 && !underwater && !inverted) s = 10;` — a ball drifting down at
 * less than a pixel a tick is snapped up to exactly one. Without it the truncating
 * division above would freeze it in mid-air.
 */
export const MIN_FALL_SPEED = 10;

/** `l += 6` per tick while a direction is held. */
export const RUN_ACCEL = 6;

/** `l -= 4` / `l += 4` per tick with nothing held. Overshoots zero rather than clamping. */
export const RUN_DECAY = 4;

/** The horizontal speed cap, and what `e.h` (the speed boost) raises it to. */
export const SPEED_CAP = 50;
export const SPEED_CAP_BOOSTED = 100;

/** `e.g = 300` / `e.B = 300` / `e.h = 300` — 300 ticks at 40 ms is 12 seconds. */
export const BOOST_TICKS = 300;

/** `s = ±67 + v` — the bounce impulse, before the charge `e.v` is added. */
export const JUMP_IMPULSE = 67;

/** `v += -5` per tick while the ball is large and the jump boost is off. */
export const JUMP_CHARGE_PER_TICK = 5;

/** `v += -10` on a bounce taken off a rubber surface with UP held. */
export const RUBBER_CHARGE = 10;

/** `e.B != 0` pins `|v|` to at least this, which is what makes the jump boost a boost. */
export const JUMP_BOOST_CHARGE = 80;

/** `e.e()`'s `u = 5` — ticks the burst sprite shows before the respawn. */
export const DEATH_TICKS = 5;

/** `e.F` cycles 0,1,2 and the one-pixel sideways nudge only fires on 0. */
export const NUDGE_PERIOD = 3;

/** `-20`: the ceiling bounce under inverted gravity, where the else branch halves instead. */
export const INVERTED_CEILING_SPEED = 20;

/** Score awards, from `e.d()` and `e.a(...)`'s `q.b(...)` calls. */
export const SCORE_HOOP = 500;
export const SCORE_CRYSTAL = 200;
export const SCORE_CRYSTAL_BALL = 1000;

/** `a.f()`'s `v.a(n, 0, 3)` — three lives, and `q.j < 0` is game over, so four attempts. */
export const STARTING_LIVES = 3;

/** `case 29`'s `if (q.j < 5) ++q.j` — a crystal ball past five lives only scores. */
export const MAX_LIVES = 5;

/** The bits `d.keyPressed` passes to `e.c(int)`, mirrored from `Input.DIRECTION_BIT`. */
export const KEY_LEFT = 1;
export const KEY_RIGHT = 2;
export const KEY_DOWN = 4;
export const KEY_UP = 8;

/** `e.a()`'s `y &= 0xFFFFFFF0` — release all four directions at once. */
export const KEY_DIRECTIONS = KEY_LEFT | KEY_RIGHT | KEY_DOWN | KEY_UP;

/** Java integer division: truncates toward zero. `Math.floor` is wrong on negatives. */
export function idiv(a: number, b: number): number {
  return Math.trunc(a / b);
}

/** Floor division, for the tile-index arithmetic — see `Ball.canOccupy()` for why. */
export function floorDiv(a: number, b: number): number {
  return Math.floor(a / b);
}

/**
 * Vertical acceleration and terminal velocity, from the four-way branch at the top of
 * `e.b()`. Both are in velocity units per tick, positive is downward.
 *
 * A large ball underwater is the odd one out: its terminal velocity is *negative*, so it
 * accelerates upward and floats. That is the buoyancy the instructions text describes
 * ("Large balls float in water, small balls don't"), and it is also why `e.b()` has two
 * `n5 == -30` special cases — the value doubles as a flag for "this ball is floating".
 */
export type Gravity = { readonly terminal: number; readonly accel: number };

/** `n5 == -30` is tested twice in `e.b()` as a stand-in for "large ball, underwater". */
export const FLOAT_TERMINAL = -30;

export function gravityFor(size: number, underwater: boolean): Gravity {
  if (underwater) {
    return size === BALL_LARGE
      ? { terminal: FLOAT_TERMINAL, accel: -2 }
      : { terminal: 42, accel: 6 };
  }
  return size === BALL_LARGE ? { terminal: 38, accel: 3 } : { terminal: 80, accel: 4 };
}

/**
 * `e.f` — a 12x12 mask, solid where `x + y >= 11`: the **lower-right** triangle. It is
 * cell (0,0) of the sprite sheet pixel for pixel, and `e.c(int,int,int)` reads it through
 * two mirror flags to cover all four slope orientations (see `SLOPE_MIRROR`).
 */
const SLOPE_ROWS = [
  '000000000001',
  '000000000011',
  '000000000111',
  '000000001111',
  '000000011111',
  '000000111111',
  '000001111111',
  '000011111111',
  '000111111111',
  '001111111111',
  '011111111111',
  '111111111111',
] as const;

/** `e.e` — the 12x12 ball, i.e. the deflated one's collision mask. */
const MASK_SMALL_ROWS = [
  '000011110000',
  '001111111100',
  '011111111110',
  '011111111110',
  '111111111111',
  '111111111111',
  '111111111111',
  '111111111111',
  '011111111110',
  '011111111110',
  '001111111100',
  '000011110000',
] as const;

/** `e.z` — the 16x16 ball, the normal one. */
const MASK_LARGE_ROWS = [
  '0000011111100000',
  '0001111111111000',
  '0011111111111100',
  '0111111111111110',
  '0111111111111110',
  '1111111111111111',
  '1111111111111111',
  '1111111111111111',
  '1111111111111111',
  '1111111111111111',
  '1111111111111111',
  '0111111111111110',
  '0111111111111110',
  '0011111111111100',
  '0001111111111000',
  '0000011111100000',
] as const;

/** A mask is indexed `[y][x]`, matching the Java `byte[row][column]`. */
export type Mask = readonly Uint8Array[];

function toMask(rows: readonly string[]): Mask {
  return rows.map((row) => Uint8Array.from(row, (bit) => (bit === '1' ? 1 : 0)));
}

export const SLOPE_MASK: Mask = toMask(SLOPE_ROWS);
export const MASK_SMALL: Mask = toMask(MASK_SMALL_ROWS);
export const MASK_LARGE: Mask = toMask(MASK_LARGE_ROWS);

/** `e.b(int,int)`'s `this.a == 16 ? z : e`. */
export function ballMask(size: number): Mask {
  return size === BALL_LARGE ? MASK_LARGE : MASK_SMALL;
}

/**
 * `e.c(int,int,int)`'s switch: which corner of `SLOPE_MASK` each slope id reads from.
 * The mask is indexed `f[|cellY - y|][|cellX - x|]`, so an 11 mirrors that axis.
 *
 * | ids | x, y | mask read as | solid half |
 * | --- | --- | --- | --- |
 * | 32, 36 | 0, 0 | `f[y][x]` | lower-right (as stored) |
 * | 30, 34 | 11, 11 | `f[11-y][11-x]` | upper-left |
 * | 31, 35 | 0, 11 | `f[11-y][x]` | upper-right |
 * | 33, 37 | 11, 0 | `f[y][11-x]` | lower-left |
 *
 * Ids 30-33 are the red slopes, 34-37 the blue (rubber) ones, in the same order. This
 * table is also the evidence that `DirectGraphics.ROTATE_90` is counter-clockwise — see
 * docs/ORIGINAL.md.
 */
export const SLOPE_MIRROR: Readonly<Record<number, { readonly x: number; readonly y: number }>> = {
  30: { x: 11, y: 11 },
  31: { x: 0, y: 11 },
  32: { x: 0, y: 0 },
  33: { x: 11, y: 0 },
  34: { x: 11, y: 11 },
  35: { x: 0, y: 11 },
  36: { x: 0, y: 0 },
  37: { x: 11, y: 0 },
};

/**
 * `b.a(int,int,int,int,int,int,int,int)` — inclusive AABB overlap, the MIDlet's one
 * geometry helper. Both rectangles are given as edges, and both edges are inside.
 */
export function rectsOverlap(
  left: number,
  top: number,
  right: number,
  bottom: number,
  otherLeft: number,
  otherTop: number,
  otherRight: number,
  otherBottom: number,
): boolean {
  return left <= otherRight && top <= otherBottom && otherLeft <= right && otherTop <= bottom;
}

/**
 * The overlap window `e.b(int,int)` and `e.c(int,int,int)` share, in **cell-local**
 * pixels. `dx`/`dy` are the ball's top-left relative to the cell's; add them back to get
 * a ball-local index.
 *
 * The original writes this out twice, identically, as four `if`/`else` pairs, and it is
 * not the obvious `max`/`min` clip. When the ball starts left of the cell the window runs
 * `[0, size + dx)` — the ball's right edge. When it starts inside, the window runs
 * `[dx, 12)` — the *cell's* right edge, with no check that the ball reaches that far. It
 * always does: `dx >= 0` and a ball is at least 12 across, so `dx + size >= 12`. The
 * shortcut only holds because there is no ball smaller than a cell, so it is transcribed
 * as written rather than tidied into something that would survive a third ball size.
 */
export type MaskWindow = {
  readonly fromX: number;
  readonly toX: number;
  readonly fromY: number;
  readonly toY: number;
};

export function maskWindow(dx: number, dy: number, size: number): MaskWindow {
  let fromX: number;
  let toX: number;
  if (dx >= 0) {
    fromX = dx;
    toX = TILE_SIZE;
  } else {
    fromX = 0;
    toX = size + dx;
  }

  let fromY: number;
  let toY: number;
  if (dy >= 0) {
    fromY = dy;
    toY = TILE_SIZE;
  } else {
    fromY = 0;
    toY = size + dy;
  }

  return {
    fromX,
    toX: Math.min(toX, TILE_SIZE),
    fromY,
    toY: Math.min(toY, TILE_SIZE),
  };
}

/**
 * `e.b(int,int)` — does the ball's pixel mask touch any part of this whole cell?
 *
 * `left`/`top` are the ball's world top-left (`e.o`, `e.m`); the cell is `(col, row)`.
 */
export function maskOverlapsCell(
  left: number,
  top: number,
  size: number,
  col: number,
  row: number,
): boolean {
  const dx = left - col * TILE_SIZE;
  const dy = top - row * TILE_SIZE;
  const window = maskWindow(dx, dy, size);
  const mask = ballMask(size);

  for (let x = window.fromX; x < window.toX; x++) {
    for (let y = window.fromY; y < window.toY; y++) {
      if (mask[y - dy]?.[x - dx]) return true;
    }
  }
  return false;
}

/**
 * `e.c(int,int,int)` minus its side effect — does the ball's mask touch the solid half of
 * a slope cell? The caller (`Ball`) is the one that then runs the deflection, because that
 * mutates velocity.
 */
export function maskOverlapsSlope(
  left: number,
  top: number,
  size: number,
  col: number,
  row: number,
  id: number,
): boolean {
  const mirror = SLOPE_MIRROR[id];
  if (!mirror) return false;

  const dx = left - col * TILE_SIZE;
  const dy = top - row * TILE_SIZE;
  const window = maskWindow(dx, dy, size);
  const mask = ballMask(size);

  for (let x = window.fromX; x < window.toX; x++) {
    for (let y = window.fromY; y < window.toY; y++) {
      const slope = SLOPE_MASK[Math.abs(y - mirror.y)]?.[Math.abs(x - mirror.x)] ?? 0;
      const ball = mask[y - dy]?.[x - dx] ?? 0;
      if ((slope & ball) !== 0) return true;
    }
  }
  return false;
}

/**
 * `e.b(int)` — a slope trades the ball's two velocity components, which is what makes a
 * diagonal deflect rather than stop dead. Pure, so the eight cases can be checked one by
 * one; `Ball` calls it from the slope overlap test, and only while the ball is not already
 * resting (`if (!this.n) this.b(n3)`).
 *
 * The four blue slopes (34-37) hand over the whole component; the four red ones (30-33)
 * halve it, with `>>` so a negative floors. Each case is conditional: the swap only
 * happens when the incoming velocity is not already steeper than the slope, so a ball
 * running down one keeps its speed instead of being re-aimed every tick.
 *
 * Ids outside 30..37 are returned unchanged, matching the switch's missing default.
 */
export function deflectOnSlope(vx: number, vy: number, id: number): { vx: number; vy: number } {
  switch (id) {
    case 35:
      return { vx: vx > -vy ? vx : vy, vy: vx };
    case 37:
      return { vx: -vx > vy ? vx : vy, vy: vx };
    case 34:
      return { vx: vx < vy ? vx : -vy, vy: -vx };
    case 36:
      return { vx: vx > vy ? vx : -vy, vy: -vx };
    case 31:
      return { vx: vx > -vy ? vx : vy >> 1, vy: vx };
    case 33:
      return { vx: -vx > vy ? vx : vy >> 1, vy: vx };
    case 30:
      return { vx: vx < vy ? vx : -(vy >> 1), vy: -vx };
    case 32:
      return { vx: vx > vy ? vx : -(vy >> 1), vy: -vx };
    default:
      return { vx, vy };
  }
}

/** Ball diameters, re-exported so callers need only one import. */
export { BALL_LARGE, BALL_SMALL };

/** `e`'s `t`: half the diameter, and the offset from the centre to the top-left. */
export function radiusFor(size: number): number {
  return size === BALL_LARGE ? 8 : 6;
}
