/**
 * T9 — the jump boost (ids 51-54). PLAN.md: "temporary higher bounce".
 *
 * ```java
 * case 51: case 52: case 53: case 54: { this.B = 300; n3 = 2; bl = false; }
 * ```
 *
 * Twelve seconds, like the other two boosts, and it works by *pinning* the bounce charge
 * rather than adding to it. The tick reads:
 *
 * ```java
 * if (this.B != 0) {
 *     if (-1 * Math.abs(this.v) > -80) this.v = (inverted ? 80 : -80);
 *     --this.B;
 * }
 * ```
 *
 * — i.e. whenever the charge is weaker than 80 it is set to ±80, and while the timer runs
 * the ordinary `v += -5` wind-up and the `v = 0` reset on landing are both skipped (both
 * are guarded by `B == 0`). The bounce impulse is `-67 + v`, so every bounce under the
 * boost leaves the floor at -147, against -72 unboosted, and it does so on the *first*
 * tick of contact rather than needing UP held through a landing.
 *
 * The `Math.abs` dance is the original's way of writing "if the charge is smaller than
 * 80", and it means an already-stronger charge — one built on a rubber floor — is left
 * alone.
 *
 * Like the other boosts: no hitbox, blocks the cell, not consumed, cleared by death.
 */
import { BOOST_TICKS } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 51: case 52: case 53: case 54:` — four rotations of the one sprite. */
export const JUMP_BOOST_IDS = [51, 52, 53, 54] as const;

export const jumpBoost: Entity = {
  name: 'jump boost',
  ids: JUMP_BOOST_IDS,
  kind: 'jump-boost',
  handle(cell) {
    cell.ball.jumpTicks = BOOST_TICKS;
    cell.sound = 'pickup';
    cell.free = false;
  },
};
