/**
 * T9 — the crystal ball (id 29): 1000 points and an extra life.
 *
 * ```java
 * case 29: {
 *     this.q.b(1000);
 *     if (this.q.j < 5) { ++this.q.j; this.q.C = true; }
 *     this.q.F[n][n2] = 128;
 *     n3 = 2;
 * }
 * ```
 *
 * Lives cap at five — `j < 5` then `++j`, so five is the ceiling and a sixth crystal ball
 * scores its 1000 and grants nothing. Note that `j` is "lives in hand" and the game-over
 * test is `j < 0`, so a fresh game's 3 is really four attempts and the cap of 5 is six.
 *
 * Like the crystal it has no hitbox — cell overlap is enough — and its rewrite to 128
 * drops the cell's underwater bit the same way. It does not touch the checkpoint.
 */
import { TILE_REDRAW } from '../Level.ts';
import { MAX_LIVES, SCORE_CRYSTAL_BALL } from '../Physics.ts';
import type { Entity } from './types.ts';

/** `case 29`. */
export const CRYSTAL_BALL_ID = 29;

export const crystalBall: Entity = {
  name: 'crystal ball',
  ids: [CRYSTAL_BALL_ID],
  kind: 'crystal-ball',
  handle(cell) {
    const { world } = cell;
    world.addScore(SCORE_CRYSTAL_BALL);
    if (world.lives < MAX_LIVES) {
      world.lives++;
      world.hudDirty = true;
    }
    cell.level.setRawTileAt(cell.col, cell.row, TILE_REDRAW | 0);
    cell.sound = 'pickup';
  },
};
