/**
 * T9 — the hoops. Fifteen of the switch's cases, one mechanic, and PLAN.md's one-line
 * summary ("pass through to clear; all hoops cleared → door opens") hides all of it.
 *
 * ## Four flavours, two cells each
 *
 * | flavour | live ids | spent ids | axis | fits |
 * | --- | --- | --- | --- | --- |
 * | orange B | 13, 14 | 17, 18 | vertical | small ball only |
 * | orange B | 15, 16 | 19, 20 | horizontal | small ball only |
 * | orange A | 21, 22 | 25, 26 | vertical | either size |
 * | orange A | 23, 24 | 27, 28 | horizontal | either size |
 *
 * Taking one rewrites **both** cells to `id + 4` with the redraw flag and the cell's
 * underwater bit preserved (`0x91 | n3` … `0x9C | n3`), scores 500 once, bumps the hoop
 * counter and plays the `up` tone. The counter is what `Playfield` compares against the
 * level header's hoop count to start the door sliding, so a hoop is only ever taken once
 * — the spent ids have no scoring path at all.
 *
 * Each cell has two hitboxes and they do different jobs:
 *
 * - **the ring** — `overlapsCellBox`, the cell narrowed 4px along the hoop's short axis.
 *   Overlapping it is what *collects* the hoop.
 * - **the bar** — `overlapsHoopBar`, the solid rim. Per-id insets, transcribed rather
 *   than derived; id 21/25 collapses to a single scanline one pixel above the cell, which
 *   is what makes the top of an upright hoop catch a ball dropping onto it.
 *
 * ## The inconsistencies, all four of them
 *
 * These are the original's and they are load-bearing enough to list:
 *
 * 1. **Only `case 23` aborts on the bar.** It sets `bl = false` and `break`s, so a ball
 *    that clips the left rim of a wide any-size hoop is blocked *and scores nothing*. The
 *    other six bar-testing cases set `bl = false` and then fall through and score anyway
 *    — blocked and collected in the same tick.
 * 2. **`case 22` and `case 14` never test the bar.** The trailing half of a vertical hoop
 *    is pure collectible; its rim is not solid.
 * 3. **The size gate is only on the small-only flavour**, and it is checked *before* the
 *    bar: a large ball at 13/14/15/16 is blocked by the whole ring box and never reaches
 *    the bar test. That gate is the deflator's entire reason to exist.
 * 4. **Spent hoops collide differently by id.** 17/19/20 block a large ball outright and
 *    otherwise only their bar is solid; 25/27/28 keep their bar for any size; 18 blocks a
 *    large ball and nothing else; 26 stops colliding altogether (it lives in
 *    `Inert.ts`).
 */
import { TILE_REDRAW } from '../Level.ts';
import { BALL_LARGE } from '../Physics.ts';
import type { Entity } from './types.ts';

/** What the bar test does on a hit, per id. */
type BarRule =
  /** `bl = false; break;` — blocked, and the hoop is *not* collected. Id 23 alone. */
  | 'abort'
  /** `if (bar) bl = false;` then score anyway. The other five. */
  | 'flag'
  /** No bar test at all. Ids 14 and 22. */
  | 'skip';

type LiveHoop = {
  /** The other half's id; its cell is rewritten too. */
  readonly partner: number;
  /** Where that half is, relative to this cell. */
  readonly dcol: number;
  readonly drow: number;
  /** The 13-16 flavour: a large ball cannot fit and is blocked by the ring. */
  readonly smallOnly: boolean;
  readonly bar: BarRule;
};

/** `case 13` … `case 24`, the eight live halves. */
export const LIVE_HOOPS: Readonly<Record<number, LiveHoop>> = {
  13: { partner: 14, dcol: 0, drow: 1, smallOnly: true, bar: 'flag' },
  14: { partner: 13, dcol: 0, drow: -1, smallOnly: true, bar: 'skip' },
  15: { partner: 16, dcol: 1, drow: 0, smallOnly: true, bar: 'flag' },
  16: { partner: 15, dcol: -1, drow: 0, smallOnly: true, bar: 'flag' },
  21: { partner: 22, dcol: 0, drow: 1, smallOnly: false, bar: 'flag' },
  22: { partner: 21, dcol: 0, drow: -1, smallOnly: false, bar: 'skip' },
  23: { partner: 24, dcol: 1, drow: 0, smallOnly: false, bar: 'abort' },
  24: { partner: 23, dcol: -1, drow: 0, smallOnly: false, bar: 'flag' },
};

/** A live half's spent id. The rewrite is literally `id + 4` for all eight. */
export const SPENT_OFFSET = 4;

export const LIVE_HOOP_IDS = Object.keys(LIVE_HOOPS).map(Number);

/** `case 17: case 19: case 20:` — large ball blocked outright, small ball by the bar. */
export const SPENT_SMALL_ONLY_IDS = [17, 19, 20] as const;

/** `case 25: case 27: case 28:` — the bar stays solid whatever size the ball is. */
export const SPENT_BAR_IDS = [25, 27, 28] as const;

/** `case 18` — the spent bottom half of an upright small hoop. Blocks a large ball. */
export const SPENT_LARGE_BLOCK_ID = 18;

export const hoop: Entity = {
  name: 'hoop',
  ids: LIVE_HOOP_IDS,
  kind: 'hoop',
  handle(cell) {
    const { ball, level, id } = cell;
    const spec = LIVE_HOOPS[id];
    if (!spec) return;

    if (!ball.overlapsCellBox(cell.row, cell.col, id)) return;

    if (spec.smallOnly && ball.size === BALL_LARGE) {
      cell.free = false;
      return;
    }

    if (spec.bar !== 'skip' && ball.overlapsHoopBar(cell.row, cell.col, id)) {
      cell.free = false;
      if (spec.bar === 'abort') return;
    }

    ball.scoreHoop();
    level.setRawTileAt(cell.col, cell.row, TILE_REDRAW | (id + SPENT_OFFSET) | cell.water);
    level.setRawTileAt(
      cell.col + spec.dcol,
      cell.row + spec.drow,
      TILE_REDRAW | (spec.partner + SPENT_OFFSET) | cell.water,
    );
    cell.sound = 'up';
  },
};

export const spentHoop: Entity = {
  name: 'spent hoop',
  ids: [...SPENT_SMALL_ONLY_IDS, ...SPENT_BAR_IDS, SPENT_LARGE_BLOCK_ID],
  kind: 'hoop-collected',
  handle(cell) {
    const { ball, id } = cell;

    if (id === SPENT_LARGE_BLOCK_ID) {
      if (ball.overlapsCellBox(cell.row, cell.col, id) && ball.size === BALL_LARGE) {
        cell.free = false;
      }
      return;
    }

    if (SPENT_BAR_IDS.includes(id as (typeof SPENT_BAR_IDS)[number])) {
      if (ball.overlapsHoopBar(cell.row, cell.col, id)) cell.free = false;
      return;
    }

    // 17, 19, 20.
    if (!ball.overlapsCellBox(cell.row, cell.col, id)) return;
    if (ball.size === BALL_LARGE) {
      cell.free = false;
      return;
    }
    if (ball.overlapsHoopBar(cell.row, cell.col, id)) cell.free = false;
  },
};
